/**
 * Signing v2 (lib/signing-v2.ts, canonicalAnswerV2 in lib/remote-prompts.ts) pinned to Botsun's
 * reference implementation: every vector in test/fixtures/signing-v2.json (generated by Botsun's
 * scripts/gen-signing-vectors.rb with a throwaway key) is rebuilt here and its signature checked.
 */
import assert from "node:assert/strict";
import { createHash, createPublicKey, verify } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { canonicalAnswerV2 } from "../lib/remote-prompts.ts";
import { digestHex, fieldsPayload, messageV2, messageV3, validHost } from "../lib/signing-v2.ts";

const FIXTURE = new URL("./fixtures/signing-v2.json", import.meta.url);
/** sha256 of the fixture as copied from Botsun; a change here means re-copying it on purpose. */
const FIXTURE_SHA256 = "4e56dcbdc3b64b67519a4a1e8d37623993be5465d2c510b2f9bbe2eb07d0fa8d";
const BOTSUN_FIXTURE = "/Users/ericboehs/Code/github.com/ericboehs/botsun/test/fixtures/signing-v2.json";
const P256_SPKI = Buffer.from("3059301306072a8648ce3d020106082a8648ce3d030107034200", "hex");

const bytes = readFileSync(FIXTURE);
const fixture = JSON.parse(bytes.toString("utf8"));
const pub = createPublicKey({ key: Buffer.concat([P256_SPKI, Buffer.from(fixture.public_key_b64, "base64")]), format: "der", type: "spki" });

test("the fixture is the pinned copy", () => {
	assert.equal(createHash("sha256").update(bytes).digest("hex"), FIXTURE_SHA256);
});

test("the fixture is byte-identical to Botsun's, when Botsun is checked out here", { skip: !existsSync(BOTSUN_FIXTURE) && "no Botsun checkout" }, () => {
	assert.ok(readFileSync(BOTSUN_FIXTURE).equals(bytes), "re-copy botsun/test/fixtures/signing-v2.json");
});

function payloadOf(v) {
	if ("payload_utf8" in v) return v.payload_utf8;
	if ("payload_b64" in v) return Buffer.from(v.payload_b64, "base64");
	if ("fields" in v) return fieldsPayload(v.fields);
	if ("answer" in v) {
		const { ask_id, questions, answers } = v.answer;
		// Botsun's questions say multi_select; a RemoteQuestion says multiSelect.
		const qs = questions.map(({ multi_select, ...q }) => ({ ...q, multiSelect: multi_select === true }));
		return canonicalAnswerV2(ask_id, qs, answers);
	}
	throw new Error(`no payload form in ${v.name}`);
}

test("every vector: payload, digest and message match Ruby's, and the signature verifies", () => {
	assert.equal(fixture.version, 2);
	assert.equal(fixture.vectors.length, 23);
	for (const v of fixture.vectors) {
		const payload = payloadOf(v);
		if ("expect_payload_b64" in v) assert.equal(Buffer.from(payload).toString("base64"), v.expect_payload_b64, v.name);
		else assert.equal(payload, v.expect_payload, v.name);
		assert.equal(digestHex(payload), v.expect_digest, v.name);
		const msg = messageV2({ deviceId: String(fixture.device_id), nonce: fixture.nonce, kind: v.kind, scope: v.scope, decision: v.decision, payload });
		assert.equal(msg, v.expect_message, v.name);
		const sig = Buffer.from(v.signature_der_b64, "base64");
		assert.equal(verify("sha256", Buffer.from(msg, "utf8"), { key: pub, dsaEncoding: "der" }, sig), true, v.name);
		assert.equal(verify("sha256", Buffer.from(`${msg}x`, "utf8"), { key: pub, dsaEncoding: "der" }, sig), false, `${v.name}: tampered`);
	}
});

// A locked phone's pick (call key): kind session, decision answer_call, over the same canonical
// answer as a main-key answer of one pick, so only the message's kind and decision tell them apart.
test("the answer_call vector: one single-select question, one pick, no text; not a main-key answer's message", () => {
	for (const [fx, version] of [[fixture, 2], [fixtureV3, 3]]) {
		const v = fx.vectors.find((x) => x.decision === "answer_call");
		assert.ok(v, `v${version} has an answer_call vector`);
		assert.equal(v.kind, "session");
		assert.equal(v.answer.questions.length, 1);
		assert.equal(v.answer.questions[0].multi_select, false);
		assert.deepEqual(v.answer.answers, [{ picks: [1] }]);
		assert.match(payloadOf(v), /\na0 1 e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855$/);
		const main = { deviceId: String(fx.device_id), nonce: fx.nonce, kind: "answer", scope: v.scope, decision: "answer", payload: payloadOf(v) };
		const mainMsg = version === 3 ? messageV3({ ...main, host: v.host }) : messageV2(main);
		const key = version === 3 ? pubV3 : pub;
		assert.equal(verify("sha256", Buffer.from(mainMsg, "utf8"), { key, dsaEncoding: "der" }, Buffer.from(v.signature_der_b64, "base64")), false);
	}
});

test("messageV2 and canonicalAnswerV2 refuse fields that could smuggle a line", () => {
	const base = { deviceId: "7", nonce: "n", kind: "session", scope: "s", decision: "say", payload: "" };
	assert.throws(() => messageV2({ ...base, deviceId: "7\n8" }));
	assert.throws(() => messageV2({ ...base, scope: "a b" }));
	assert.throws(() => messageV2({ ...base, decision: "" }));
	assert.throws(() => fieldsPayload([["a b", "x"]]));
	const q = [{ question: "Q?", options: [{ label: "A" }] }];
	assert.throws(() => canonicalAnswerV2("a\nb", q, [{ picks: [0] }]));
	assert.throws(() => canonicalAnswerV2("id1", q, []), /one answer per question/);
	assert.throws(() => canonicalAnswerV2("id1", q, [{ picks: ["0"] }]));
	assert.notEqual(canonicalAnswerV2("id1", q, [{ picks: [0] }]),
		canonicalAnswerV2("id1", [{ ...q[0], options: [{ label: "B" }] }], [{ picks: [0] }]), "the options are signed");
});

// ---- v3 (botsun-sign-v3: v2 plus the host's authority) ----------------------

const FIXTURE_V3 = new URL("./fixtures/signing-v3.json", import.meta.url);
/** sha256 of the v3 fixture as copied from Botsun; a change here means re-copying it on purpose. */
const FIXTURE_V3_SHA256 = "3bc34ddcc82d1cb902c751d40f089f6f91e5379285a11a35668b043f14dbda43";
const BOTSUN_FIXTURE_V3 = "/Users/ericboehs/Code/github.com/ericboehs/botsun/test/fixtures/signing-v3.json";
const bytesV3 = readFileSync(FIXTURE_V3);
const fixtureV3 = JSON.parse(bytesV3.toString("utf8"));
const pubV3 = createPublicKey({ key: Buffer.concat([P256_SPKI, Buffer.from(fixtureV3.public_key_b64, "base64")]), format: "der", type: "spki" });

test("v3: the fixture is the pinned copy", () => {
	assert.equal(createHash("sha256").update(bytesV3).digest("hex"), FIXTURE_V3_SHA256);
});

test("v3: the fixture is byte-identical to Botsun's, when Botsun is checked out here", { skip: !existsSync(BOTSUN_FIXTURE_V3) && "no Botsun checkout" }, () => {
	assert.ok(readFileSync(BOTSUN_FIXTURE_V3).equals(bytesV3), "re-copy botsun/test/fixtures/signing-v3.json");
});

test("v3: every vector's message matches Ruby's and verifies; with another host (or as v2) it doesn't", () => {
	assert.equal(fixtureV3.version, 3);
	assert.equal(fixtureV3.vectors.length, 24);
	const hosts = new Set(fixtureV3.vectors.map((v) => v.host));
	assert.ok(hosts.has("botsun.boehs.com:8443") && hosts.has("coop.botsun.boehs.com:8443"));
	for (const v of fixtureV3.vectors) {
		const payload = payloadOf(v);
		if ("expect_payload_b64" in v) assert.equal(Buffer.from(payload).toString("base64"), v.expect_payload_b64, v.name);
		else assert.equal(payload, v.expect_payload, v.name);
		assert.equal(digestHex(payload), v.expect_digest, v.name);
		const m = { deviceId: String(fixtureV3.device_id), nonce: fixtureV3.nonce, kind: v.kind, scope: v.scope, decision: v.decision, payload };
		const msg = messageV3({ ...m, host: v.host });
		assert.equal(msg, v.expect_message, v.name);
		assert.equal(msg.split("\n")[1], v.host, v.name);
		const sig = Buffer.from(v.signature_der_b64, "base64");
		const ok = (text) => verify("sha256", Buffer.from(text, "utf8"), { key: pubV3, dsaEncoding: "der" }, sig);
		assert.equal(ok(msg), true, v.name);
		const other = v.host === "botsun.boehs.com:8443" ? "coop.botsun.boehs.com:8443" : "botsun.boehs.com:8443";
		assert.equal(ok(messageV3({ ...m, host: other })), false, `${v.name}: another host`);
		assert.equal(ok(messageV2(m)), false, `${v.name}: as v2`);
	}
});

test("v3: invalid hosts are refused (no message is built)", () => {
	assert.ok(fixtureV3.invalid.length >= 3);
	for (const v of fixtureV3.invalid) {
		assert.equal(v.expect_error, true, v.name);
		assert.equal(validHost(v.host), false, v.name);
		assert.throws(() => messageV3({ deviceId: String(fixtureV3.device_id), nonce: fixtureV3.nonce, kind: v.kind, scope: v.scope,
			decision: v.decision, payload: payloadOf(v), host: v.host }), /bad host/, v.name);
	}
	for (const host of ["botsun.boehs.com:8443\n", "", ":8443", "-a.b:1", "a.b:123456", "a b:1", undefined]) assert.equal(validHost(host), false, JSON.stringify(host));
	for (const host of ["botsun.boehs.com:8443", "a:1", "127.0.0.1:8443"]) assert.equal(validHost(host), true, host);
});
